#!/usr/bin/env bash
# Entrypoint: patch network placeholders in config, then exec COMP.
# Placeholders (optional): __EXTERNAL_IP__ __LOBBY_HOST__ __WORLD_HOST__ __MARIADB_HOST__
# Patched file stays next to the source so sibling constants.xml resolves.
# comp_channel only: when STUDIO_TOKEN is set (deploy/.env, generated by install.sh), the
# runtime channel.xml gets StudioToken=$STUDIO_TOKEN and StudioHttpPort=14700 if unset/0,
# so the website reaches the studio API at http://channel:14700 with no manual config.
set -euo pipefail

# stdin → stdout: set StudioToken (and StudioHttpPort when missing/0) in a channel objgen XML.
# Members are one per line (`<member name="X">v</member>`); new ones go before the last
# </object> (the top-level ChannelConfig object).
studio_patch() {
  local token="${STUDIO_TOKEN:-}"
  local default_port="${STUDIO_HTTP_PORT_DEFAULT:-14700}"
  if [[ -z "$token" ]]; then
    cat
    return 0
  fi
  if [[ ! "$token" =~ ^[A-Za-z0-9._~+/=-]+$ ]]; then
    echo "entrypoint: STUDIO_TOKEN has unsupported characters; leaving channel.xml StudioToken as is" >&2
    cat
    return 0
  fi
  awk -v tok="$token" -v defport="$default_port" '
    { lines[NR] = $0 }
    /<\/object>/ { last_close = NR }
    END {
      port = ""
      for (i = 1; i <= NR; i++) {
        if (lines[i] ~ /<member[^>]*name="StudioHttpPort"/) {
          v = lines[i]
          sub(/.*name="StudioHttpPort"[^>]*>/, "", v)
          sub(/<\/member>.*/, "", v)
          gsub(/[ \t]/, "", v)
          if (v ~ /^[0-9]+$/ && v + 0 > 0) port = v
        }
      }
      if (port == "") port = defport
      for (i = 1; i <= NR; i++) {
        if (lines[i] ~ /<member[^>]*name="(StudioToken|StudioHttpPort)"/) continue
        if (i == last_close) {
          indent = lines[i]
          sub(/<.*/, "", indent)
          print indent "    <member name=\"StudioHttpPort\">" port "</member>"
          print indent "    <member name=\"StudioToken\">" tok "</member>"
        }
        print lines[i]
      }
    }
  '
}

# Sourced (tests): define functions only.
if [[ "${BASH_SOURCE[0]}" != "$0" ]]; then
  return 0
fi

# Password reset secret shared with website (written by Admin → Email settings).
if [[ -f /website-data/comp-reset-secret ]]; then
  COMP_RESET_SECRET="$(tr -d '\n\r' < /website-data/comp-reset-secret)"
  export COMP_RESET_SECRET
fi

mkdir -p /comp/config /comp/database /comp/datastore /comp/webroot /comp/logs
cd /comp

if [[ $# -lt 1 ]]; then
  echo "usage: $0 comp_lobby|comp_world|comp_channel [config.xml]" >&2
  exit 1
fi

bin="$1"
shift

if [[ $# -ge 1 && -f "$1" ]]; then
  src="$1"
  shift
  # Same directory as source (COMP resolves constants.xml beside the config).
  tmp="$(dirname "$src")/.runtime-$(basename "$src")"
  external_ip="${EXTERNAL_IP:-127.0.0.1}"
  lobby_host="${LOBBY_HOST:-lobby}"
  world_host="${WORLD_HOST:-world}"
  mariadb_host="${MARIADB_HOST:-mariadb}"
  sed \
    -e "s|__EXTERNAL_IP__|${external_ip}|g" \
    -e "s|__LOBBY_HOST__|${lobby_host}|g" \
    -e "s|__WORLD_HOST__|${world_host}|g" \
    -e "s|__MARIADB_HOST__|${mariadb_host}|g" \
    "$src" >"$tmp"
  if [[ "$(basename "$bin")" == "comp_channel" && -n "${STUDIO_TOKEN:-}" ]]; then
    studio_patch <"$tmp" >"$tmp.studio" && mv -f "$tmp.studio" "$tmp"
    echo "entrypoint: channel studio API on :$(grep -o 'name="StudioHttpPort">[0-9]*' "$tmp" | grep -o '[0-9]*$' || true) (StudioToken from STUDIO_TOKEN)"
  fi
  exec "$bin" "$tmp" "$@"
fi

exec "$bin" "$@"
